@Transactional
public TaskView completeTask(String incidentKey, String taskKey, String actor, TaskActionRequest req) {
    String commandKey = requireText(req.commandKey(), "commandKey");
    Incident incident = lockIncident(incidentKey);
    return runIdempotent(commandKey, "task_complete", hash(incidentKey, taskKey, actor), TaskView.class, () -> {
        requireCommander(incident, actor);
        IncidentTask task = tasks.findByKey(incident.id(), taskKey)
                .orElseThrow(() -> notFound("任务不存在: " + taskKey));
        if (task.status() != TaskStatus.OPEN)
            throw conflict("任务已处于终态 " + task.status() + "，不能完成");
        List<String> unresolved = unresolvedBlockers(task.id());
        if (!unresolved.isEmpty())
            throw conflict("存在未解除阻塞的事件", List.copyOf(unresolved));
        Instant now = now();
        tasks.markDone(task.id(), actor, now);
        return toTaskView(tasks.findByKey(incident.id(), taskKey).orElseThrow());
    });
}
